import{_ as s,a0 as a,w as l,s as p,ao as c,I as e,x as t,a1 as r,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux 有問必答： 如何在Linux中加入cron任務 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答： 如何在Linux中加入cron任務 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答： 如何在Linux中加入cron任務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答： 如何在Linux中加入cron任務 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150122 Linux FAQs with Answers--How to add a cron job on Linux","title":"Linux 有問必答： 如何在Linux中加入cron任務","tag":"201502","desc":""},"relativePath":"201502/20150122 Linux FAQs with Answers--How to add a cron job on Linux.md","filePath":"[post].md"}'),d={name:"201502/20150122 Linux FAQs with Answers--How to add a cron job on Linux.md"};function u(m,n,x,g,h,L){const o=a("Link");return l(),p("div",null,[n[11]||(n[11]=c(`<h1 id="linux-有問必答-如何在linux中加入cron任務" tabindex="-1">Linux 有問必答： 如何在Linux中加入cron任務 <a class="header-anchor" href="#linux-有問必答-如何在linux中加入cron任務" aria-label="Permalink to “Linux 有問必答： 如何在Linux中加入cron任務”">​</a></h1><blockquote><p><strong>提問</strong>： 我想在我的Linux中安排一個計劃任務，該任務在固定時間週期性地運行。我該如何在Linux中添加一個cron任務？</p></blockquote><p>cron是Linux中默認的計劃任務。使用cron，你可以安排一個計劃（比如：命令或者shell腳本）週期性地運行或者在指定的分鐘、小時、天、周、月等特定時間運行。cron在你安排不同的常規維護任務時是很有用的，比如週期性地備份、日誌循環、檢查文件系統、監測磁盤空間等等。</p><h3 id="從命令列中添加cron任務" tabindex="-1">從命令列中添加cron任務 <a class="header-anchor" href="#從命令列中添加cron任務" aria-label="Permalink to “從命令列中添加cron任務”">​</a></h3><p>要添加cron任務，你可以使用稱為crontab的命令列工具。</p><p>輸入下面的命令會創建一個以當前用户運行的新cron任務。</p><pre><code>$ crontab -e
</code></pre><p>如果你想要以其他用户運行cron任務，輸入下面的命令。</p><pre><code>$ sudo crontab -u &lt;username&gt; -e
</code></pre><p>你將會看見一個文本編輯窗口，這裏你可以添加或者編輯cron任務。默認使用nono編輯器。</p><p><img src="https://farm9.staticflickr.com/8586/16200331362_1385807ac0_b.jpg" alt=""></p><p>每個cron任務的格式如下。</p><pre><code>&lt;分鐘&gt; &lt;小時&gt; &lt;日&gt; &lt;月&gt; &lt;星期&gt; &lt;命令&gt;
</code></pre><p>前5個元素定義了任務的計劃，最後一個元素是命令或者腳本的完整路徑。</p><p><img src="https://farm8.staticflickr.com/7472/16199272841_dffe0b2873_b.jpg" alt=""></p><p>下面是一些cron任務示例。</p><ul><li><strong>* * * * * /home/dan/bin/script.sh</strong>: 每分鐘運行。</li><li><strong>0 * * * * /home/dan/bin/script.sh</strong>: 每小時運行。</li><li><strong>0 0 * * * /home/dan/bin/script.sh</strong>: 每天零點運行。</li><li><strong>0 9,18 * * * /home/dan/bin/script.sh</strong>: 在每天的9AM和6PM運行。</li><li><strong>0 9-18 * * * /home/dan/bin/script.sh</strong>: 在9AM到6PM的每個小時運行。</li><li><strong>0 9-18 * * 1-5 /home/dan/bin/script.sh</strong>: 週一到週五的9AM到6PM每小時運行。</li><li><strong>*/10 * * * * /home/dan/bin/script.sh</strong>: 每10分鐘運行。</li></ul><p>一旦完成上面的設置步驟後，按下Ctrl+X來保存並退出編輯器。此時，新增的計劃任務應該已經激活了。</p><p>要查看存在的計劃任務，使用下面的命令：</p><pre><code>$ crontab -l
</code></pre><h3 id="從gui添加計劃任務" tabindex="-1">從GUI添加計劃任務 <a class="header-anchor" href="#從gui添加計劃任務" aria-label="Permalink to “從GUI添加計劃任務”">​</a></h3><p>如果你在Linux桌面環境中，你可以使用crontab的更加友好的GUI前端來添加或者添加一個cron任務。</p><p>在Gnome桌面中，有一個Gnome Schedule（gnome-schedule包）。</p><p><img src="https://farm8.staticflickr.com/7484/16015054699_d96f0e9b6a_c.jpg" alt=""></p><p>在KDE桌面中，有一個Task Scheduler（kcron包）。</p><p><img src="https://farm8.staticflickr.com/7473/16175298266_825376c901_c.jpg" alt=""></p><hr>`,27)),e("p",null,[n[1]||(n[1]=t("via: ",-1)),r(o,{href:"http://ask.xmodulo.com/add-cron-job-linux.html"},{default:i(()=>[...n[0]||(n[0]=[t("http://ask.xmodulo.com/add-cron-job-linux.html",-1)])]),_:1})]),e("p",null,[n[4]||(n[4]=t("譯者：",-1)),r(o,{href:"https://github.com/geekpi"},{default:i(()=>[...n[2]||(n[2]=[t("geekpi",-1)])]),_:1}),n[5]||(n[5]=t(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:i(()=>[...n[3]||(n[3]=[t("wxy",-1)])]),_:1})]),e("p",null,[n[8]||(n[8]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...n[6]||(n[6]=[t("LCTT",-1)])]),_:1}),n[9]||(n[9]=t(" 原創翻譯，",-1)),r(o,{href:"http://linux.cn/"},{default:i(()=>[...n[7]||(n[7]=[t("Linux中國",-1)])]),_:1}),n[10]||(n[10]=t(" 榮譽推出",-1))])])}const T=s(d,[["render",u]]);export{_ as __pageData,T as default};
